using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Codice.Characters;using Codice.Enemies;using Codice.Bosses;
public static class ConnectFourthContent {
 static void Tint(GameObject g,string label,Color color){int i=0;foreach(var r in g.GetComponentsInChildren<Renderer>(true)){r.sharedMaterials=r.sharedMaterials.Select(m=>{if(!m)return m;string p="Assets/Resources/WorldFour/"+label+"-"+(i++)+".mat";var copy=AssetDatabase.LoadAssetAtPath<Material>(p);if(!copy){copy=new Material(m);AssetDatabase.CreateAsset(copy,p);}if(copy.HasProperty("_BaseColor"))copy.SetColor("_BaseColor",color);if(copy.HasProperty("_Metallic"))copy.SetFloat("_Metallic",.35f);EditorUtility.SetDirty(copy);return copy;}).ToArray();}}
 public static string Run(){
 string mp="Assets/Resources/CindersDungeon/Merchant.prefab";var merchant=PrefabUtility.LoadPrefabContents(mp);try{var m=merchant.GetComponent<Merchant>();if(m.visual&&m.visual!=merchant)m.visual.SetActive(false);var old=merchant.transform.Find("Nereo · Tasador");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var body=(GameObject)PrefabUtility.InstantiatePrefab(Resources.Load<GameObject>("WorldProgression/Nereo"),merchant.transform);body.name="Nereo · Tasador";body.transform.localPosition=Vector3.zero;body.transform.localRotation=Quaternion.identity;body.transform.localScale=Vector3.one;m.visual=body;var collider=merchant.GetComponent<CapsuleCollider>()??merchant.AddComponent<CapsuleCollider>();collider.center=Vector3.up*.9f;collider.height=1.8f;collider.radius=.4f;collider.isTrigger=true;m.interactionCollider=collider;PrefabUtility.SaveAsPrefabAsset(merchant,mp);}finally{PrefabUtility.UnloadPrefabContents(merchant);}
 Directory.CreateDirectory("Assets/Resources/WorldFour/Enemies");Directory.CreateDirectory("Assets/Resources/WorldFour/Bosses");AssetDatabase.Refresh();
 string[] names={"Executioner","Watcher","StrawReaper"};string[] titles={"Forjador sin nombre","Notario de ceniza","Deudor del horno"};for(int i=0;i<names.Length;i++){var g=PrefabUtility.LoadPrefabContents("Assets/Resources/ExpeditionEnemies/Cemetery/"+names[i]+".prefab");try{g.name=titles[i];Tint(g,"Resident"+i,i==1?new Color(.35f,.51f,.57f):new Color(.49f,.32f,.20f));var e=g.GetComponent<BasicEnemy>();e.variantName=titles[i];e.healthMultiplier*=1.15f;e.damageMultiplier*=1.1f;PrefabUtility.SaveAsPrefabAsset(g,"Assets/Resources/WorldFour/Enemies/"+names[i]+".prefab");}finally{PrefabUtility.UnloadPrefabContents(g);}}
 string[] source={"MonsterMutant","Gurdi del Abismo","Necromancer"};string[] bossNames={"Maestre de Escoria","Custodio del Contrapeso","La Voz del Horno"};for(int i=0;i<3;i++){var g=PrefabUtility.LoadPrefabContents("Assets/Resources/ExpeditionEnemies/"+source[i]+".prefab");try{g.name=bossNames[i];var b=g.GetComponent<BossCharacter>();b.baseHealth=2200+i*350;b.goldReward=750+i*150;Tint(g,"Boss"+i,i==1?new Color(.29f,.42f,.5f):new Color(.62f,.41f,.23f));if(i==2)b.summons=names.Select(n=>Resources.Load<BasicEnemy>("WorldFour/Enemies/"+n)).ToArray();PrefabUtility.SaveAsPrefabAsset(g,"Assets/Resources/WorldFour/Bosses/"+bossNames[i]+".prefab");}finally{PrefabUtility.UnloadPrefabContents(g);}}
 AssetDatabase.SaveAssets();return "Nereo connected; three enemy and three boss variants saved with existing animation/AI";
 }
}
